// contractAssertReplayZeroOnError asserts Replay returns nothing alongside any error.
func contractAssertReplayZeroOnError(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := c.Replay(ctx)
	if err == nil {
		tb.Skip("Replay answered for a cancelled context, so this check has no error to inspect")
	}

	if got != nil {
		tb.Errorf("Replay must return nothing alongside an error (err %v)", err)
	}
}

