// --- Contract's model tier -------------------------------------------
//
// Random sequences of Contract's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and ContractSuite.Without declines any of them by name.
//
//	Reference: derived — the AppendOnly oracle, which is the
//	           chain contract's own semantics; NewContractModelReference replaces it
//	Sequences: Append (chain.append), Replay (collector), Verify (lifecycle)
//	Laws:      AUTO-HASH-CHAIN-INTEGRITY-VERIFY
//	Not bound:
//	           AUTO-WRITE-OBSERVABLE — Read names the reader family, and the interface has no keyed reader

// contractModelKeys is the key pool every key slot draws from.
//
// Two keys, and deliberately not more: collision density is what makes a
// read revisit a write and an overwrite land on held state. A wide key
// pool would pass every comparison over a history that never collides.
func contractModelKeys(fx ContractFixture) *model.Generator[chain.Entry] {
	return model.SampledFrom([]chain.Entry{fx.Entry(), fx.EntryOther()})
}

// contractModelReference adapts the shipped AppendOnly oracle — the
// chain contract's own semantics — to Contract.
// Deliberately simple: its correctness is read, not tested.
type contractModelReference struct {
	store *ref.AppendOnly[chain.Entry]
}

// NewContractModelReference builds one. Exported because a consumer whose
// semantics outrun their shape replaces it, and because the proof beside
// this file drives it as a subject of its own.
func NewContractModelReference() Contract {
	return &contractModelReference{store: ref.NewAppendOnly[chain.Entry](
		ref.DefaultChainHash[chain.Entry](),
	)}
}

func (r *contractModelReference) Append(ctx context.Context, e chain.Entry) error {
	return r.store.Append(ctx, e)
}

// Replay drains the oracle's iterator into the slice the contract
// answers — the one seam between the two spellings of a replay.
func (r *contractModelReference) Replay(ctx context.Context) ([]chain.Entry, error) {
	out := []chain.Entry{}
	for e, err := range r.store.Replay(ctx) {
		if err != nil {
			return nil, err
		}
		out = append(out, e)
	}
	return out, nil
}

func (r *contractModelReference) Verify(ctx context.Context) error {
	return r.store.Verify(ctx)
}

// contractModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func contractModelActions(fx ContractFixture, appendHist *history.History[string, chain.Entry]) []model.Action[Contract] {
	keys := contractModelKeys(fx)
	return []model.Action[Contract]{
		action.ChainAppend("Append", keys,
			func(ctx context.Context, s chain.Contract, v chain.Entry) error {
				err := s.Append(ctx, v)
				if err == nil {
					appendHist.Record("", v)
				}
				return err
			}),
		action.Stream("Replay",
			func(ctx context.Context, s chain.Contract) ([]chain.Entry, error) {
				return s.Replay(ctx)
			}),
		action.Lifecycle("Verify",
			func(ctx context.Context, s chain.Contract) error {
				return s.Verify(ctx)
			}),
	}
}

// contractModelLaws is the laws the classifications earned and this build
// could fill.
//
// Observational, every one of them: a law never mutates, so running them
// inside the sequences is safe for every step that follows. What they
// judge is the subject's own behaviour, which is why they are a separate
// leg from the reference comparison rather than more oracles on it.
func contractModelLaws(fx ContractFixture, appendHist *history.History[string, chain.Entry]) []law.Law[Contract] {
	return []law.Law[Contract]{
		law.HashChainIntegrityViaVerify[chain.Contract]{
			Verify: func(rt *model.T, s chain.Contract) error {
				return s.Verify(rt.Context())
			},
		},
	}
}

// contractAssertLaws drives the same sequences with the bound laws as the only
// oracle, and reports when they engaged nothing.
//
// The differential verdict is off here, and that is the whole reason this
// is a second leg rather than more options on the first: with it armed, a
// subject broken anywhere disagrees at step 0 and no law is ever reached,
// which makes "can this law catch a defect" unanswerable.
//
// The report is the other half. A law behind a precondition the subject
// refuses on every draw passes every time and asserts nothing, and from
// outside that is indistinguishable from a law that held.
func contractAssertLaws(
	tb testing.TB,
	sub suite.Subject[Contract],
	fx ContractFixture,
) {
	tb.Helper()
	// The log the recording actions fill and the runner clears each
	// iteration: a law reading a history the sequences never wrote into is
	// a law over an empty record.
	appendHist := history.New[string, chain.Entry]()

	// The run's declared oracle where one exists, the derived reference
	// otherwise — and the report says which, because a law held against a
	// second copy of the subject is a weaker claim than the same law held
	// against something written independently.
	buildRef, tier := legs.Reference(tb, sub, NewContractModelReference)
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(fx, appendHist),
		contractModelLaws(fx, appendHist),
		model.WithHistoryReset[Contract](appendHist.Reset))
}

// contractAssertAgrees drives random operation sequences against the subject and
